<template>
  <div class="content-management">
    <section class="admin-card featured-manager">
      <div class="content-section-head"><div><span class="admin-eyebrow">HOME · TODAY'S PICKS</span><h2>今日好物管理</h2><p>客户端首页最多展示 4 个商品，可从已有商品中选择、替换或新增商品。</p></div><span class="featured-count">{{ featuredProducts.length }} / 4</span></div>
      <div class="featured-slots">
        <div v-for="(product,index) in featuredProducts" :key="product.id" class="featured-slot"><span class="slot-index">{{ index+1 }}</span><div class="admin-product-cover" :style="{background:product.color}"><img v-if="product.cover" :src="product.cover" alt="商品封面"/><span v-else>{{ product.emoji }}</span></div><div class="featured-info"><b>{{ product.name }}</b><small>{{ product.desc }}</small><strong>¥{{ Number(product.price).toFixed(1) }}</strong></div><button class="slot-remove" @click="removeFeatured(product)">移除</button></div><div v-for="slot in emptySlots" :key="`empty-${slot}`" class="featured-slot empty-slot"><span class="slot-index">{{ featuredProducts.length+slot }}</span><span class="empty-plus">＋</span><div><b>空推荐位</b><small>从下方商品库选择商品</small></div></div></div>
    </section>
    <section class="admin-card product-library"><div class="content-section-head"><div><b>已有商品</b><p>点击“加入首页”即可替换为客户端首页今日好物，最多 4 个。</p></div><button class="admin-primary" @click="openCreate">＋ 新增商品</button></div><div class="library-grid"><article v-for="product in products" :key="product.id" class="library-product"><div class="admin-product-cover large" :style="{background:product.color}"><img v-if="product.cover" :src="product.cover" alt="商品封面"/><span v-else>{{product.emoji}}</span></div><div class="library-product-info"><b>{{product.name}}</b><small>{{product.origin || '鲜选商品'}} · {{product.unit || '份'}}</small><strong>¥{{Number(product.price).toFixed(1)}}</strong></div><button class="table-action" :disabled="isFeatured(product.id)" @click="addFeatured(product)">{{isFeatured(product.id)?'已在首页':'加入首页'}}</button></article></div></section>
    <div v-if="showCreate" class="admin-modal" @click.self="showCreate=false"><form class="admin-form" @submit.prevent="saveNewProduct"><div class="admin-form-head"><div><span class="admin-eyebrow">NEW PRODUCT</span><h2>新增首页商品</h2></div><button type="button" @click="showCreate=false">×</button></div><div class="admin-form-grid"><label>商品名称<input v-model.trim="form.name" required placeholder="例如：海南金钻凤梨"/></label><label>商品价格<input v-model.number="form.price" required min="0" step="0.1" type="number" placeholder="0.00"/></label><label>商品分类<select v-model="form.category"><option value="fruit">水果</option><option value="vegetable">蔬菜</option><option value="meat">肉禽蛋品</option><option value="seafood">水产海鲜</option><option value="staple">粮油调味</option><option value="drink">饮品乳品</option></select></label><label>商品单位<input v-model.trim="form.unit" placeholder="盒 / 袋 / 箱"/></label><label>商品产地<input v-model.trim="form.origin" placeholder="例如：海南三亚"/></label><label>默认图标<input v-model.trim="form.emoji" placeholder="例如：🍍"/></label><label class="full-admin-field">商品介绍<textarea v-model.trim="form.desc" required placeholder="请输入商品卖点和介绍"></textarea></label><label class="full-admin-field">商品封面<input type="file" accept="image/*" @change="readCover"/><small class="file-hint">也可以不上传，使用默认图标展示</small></label></div><div v-if="form.cover" class="cover-preview"><img :src="form.cover" alt="封面预览"/></div><button class="admin-primary full-admin-button" type="submit">保存商品并加入今日好物</button></form></div>
  </div>
</template>
<script setup>
import { computed, reactive, ref, inject } from 'vue'
import { createProduct, featuredProductIds, featuredProducts, products, saveFeaturedProducts } from '../../data'
const emit=defineEmits(['notify']),notify=message=>emit('notify',message),showCreate=ref(false),emptySlots=computed(()=>Math.max(0,4-featuredProducts.value.length)),form=reactive({name:'',price:null,category:'fruit',unit:'份',origin:'',emoji:'🍎',desc:'',cover:''})
const isFeatured=id=>featuredProductIds.includes(id)
const addFeatured=product=>{if(isFeatured(product.id))return;if(featuredProductIds.length>=4){notify('今日好物最多只能设置 4 个');return}featuredProductIds.push(product.id);saveFeaturedProducts();notify(`已将“${product.name}”加入首页`)}
const removeFeatured=product=>{const index=featuredProductIds.indexOf(product.id);if(index>=0){featuredProductIds.splice(index,1);saveFeaturedProducts();notify(`已从今日好物移除“${product.name}”`)}}
const openCreate=()=>{Object.assign(form,{name:'',price:null,category:'fruit',unit:'份',origin:'',emoji:'🍎',desc:'',cover:''});showCreate.value=true}
const readCover=event=>{const file=event.target.files?.[0];if(!file)return;if(file.size>8*1024*1024){notify('商品封面不能超过 8MB');return}const reader=new FileReader();reader.onload=()=>{form.cover=String(reader.result)};reader.readAsDataURL(file)}
const saveNewProduct=()=>{if(featuredProductIds.length>=4){notify('请先移除一个推荐位，再新增首页商品');return}const product=createProduct(form);featuredProductIds.push(product.id);saveFeaturedProducts();showCreate.value=false;notify('新商品已创建并加入首页')}
</script>
